import AxeBuilder from '@axe-core/playwright'
import { expect } from '@playwright/test'

export const PRODUCT_PATH = '/products/trail-runner-2'

// axe-core tag set for WCAG 2.2 Level A and AA (includes 2.0, 2.1 and 2.2 criteria).
const WCAG_22_AA_TAGS = ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa']

/**
 * Fails the test with a readable list of every WCAG 2.2 AA violation found by axe.
 * Pass a locator as `scope` to limit the scan to one widget (e.g. an open dialog).
 */
export async function expectWcag22AA(page, scope) {
  let builder = new AxeBuilder({ page }).withTags(WCAG_22_AA_TAGS)
  if (scope) builder = builder.include(scope)
  const { violations } = await builder.analyze()
  const report = violations.map(
    (v) => `${v.id} (${v.impact}): ${v.help} -> ${v.nodes.map((n) => n.target.join(' ')).join(' | ')}`,
  )
  expect(report).toEqual([])
}

/** Selects the first size in the open size list that is not sold out. */
export async function chooseAvailableSize(page) {
  const sizeCombobox = page.getByRole('combobox', { name: /size/i })
  await sizeCombobox.click()
  const available = page
    .getByRole('listbox')
    .locator('[role="option"]:not([aria-disabled="true"])')
    .first()
  await available.click()
  await expect(page.getByRole('listbox')).toBeHidden()
  return available
}

/** True when the element is a circle (border radius is at least half its smaller side). */
export async function isRound(locator) {
  return locator.evaluate((el) => {
    const { width, height } = el.getBoundingClientRect()
    const radius = parseFloat(getComputedStyle(el).borderTopLeftRadius)
    return width > 0 && Math.abs(width - height) < 0.5 && radius >= Math.min(width, height) / 2 - 0.5
  })
}

/** Reads the number of items shown on the cart control in the store header. */
export async function cartCount(page) {
  const cart = page
    .getByRole('banner')
    .getByRole('link', { name: /cart/i })
    .or(page.getByRole('banner').getByRole('button', { name: /cart/i }))
  const text = (await cart.first().textContent()) ?? ''
  const match = text.match(/\d+/)
  return match ? Number(match[0]) : NaN
}
import { test, expect } from '@playwright/test'
import { PRODUCT_PATH, expectWcag22AA } from './helpers.js'

test.describe('Store header', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto(PRODUCT_PATH)
  })

  test('shows the store name in the header', async ({ page }) => {
    await expect(page.getByRole('banner')).toContainText('Stride')
  })

  test('shows how many items are in the cart', async ({ page }) => {
    const banner = page.getByRole('banner')
    const cart = banner.getByRole('link', { name: /cart/i }).or(banner.getByRole('button', { name: /cart/i }))
    await expect(cart.first()).toBeVisible()
    await expect(cart.first()).toHaveAccessibleName(/cart.*\d+|\d+.*cart/i)
  })
})

test.describe('Search', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto(PRODUCT_PATH)
  })

  test('shows matching suggestions as the shopper types', async ({ page }) => {
    const search = page.getByRole('combobox', { name: /search/i })
    await search.pressSequentially('Trail')

    await expect(search).toHaveAttribute('aria-expanded', 'true')
    await expect(page.getByRole('option', { name: /Trail Runner 2/ }).first()).toBeVisible()
  })

  test('offers more than one suggestion so they can be moved through', async ({ page }) => {
    const search = page.getByRole('combobox', { name: /search/i })
    await search.pressSequentially('Trail')
    await expect(page.getByRole('option')).not.toHaveCount(0)
    expect(await page.getByRole('option').count()).toBeGreaterThanOrEqual(2)
  })

  test('shows no suggestions when nothing matches', async ({ page }) => {
    const search = page.getByRole('combobox', { name: /search/i })
    await search.pressSequentially('zzzz-no-such-shoe')

    await expect(page.getByRole('option')).toHaveCount(0)
    await expect(search).toHaveAttribute('aria-expanded', 'false')
  })

  test('moves through suggestions with arrow keys while focus stays in the search box (APG combobox)', async ({ page }) => {
    const search = page.getByRole('combobox', { name: /search/i })
    await search.pressSequentially('Trail')
    const options = page.getByRole('option')

    await page.keyboard.press('ArrowDown')
    const firstId = await options.nth(0).getAttribute('id')
    await expect(search).toBeFocused()
    await expect(search).toHaveAttribute('aria-activedescendant', firstId)
    await expect(options.nth(0)).toHaveAttribute('aria-selected', 'true')

    await page.keyboard.press('ArrowDown')
    await expect(search).toHaveAttribute('aria-activedescendant', (await options.nth(1).getAttribute('id')))
    await expect(options.nth(1)).toHaveAttribute('aria-selected', 'true')

    await page.keyboard.press('ArrowUp')
    await expect(search).toHaveAttribute('aria-activedescendant', firstId)
  })

  test('chooses a highlighted suggestion with Enter', async ({ page }) => {
    const search = page.getByRole('combobox', { name: /search/i })
    await search.pressSequentially('Trail')
    const options = page.getByRole('option')
    const secondText = (await options.nth(1).textContent())?.trim()

    await page.keyboard.press('ArrowDown')
    await page.keyboard.press('ArrowDown')
    await page.keyboard.press('Enter')

    await expect(search).toHaveValue(secondText)
    await expect(search).toHaveAttribute('aria-expanded', 'false')
    await expect(page.getByRole('option')).toHaveCount(0)
  })

  test('closes the suggestions with Escape and keeps focus in the search box', async ({ page }) => {
    const search = page.getByRole('combobox', { name: /search/i })
    await search.pressSequentially('Trail')
    await page.keyboard.press('Escape')

    await expect(search).toHaveAttribute('aria-expanded', 'false')
    await expect(search).toBeFocused()
  })

  test('meets WCAG 2.2 AA with suggestions open', async ({ page }) => {
    await page.getByRole('combobox', { name: /search/i }).pressSequentially('Trail')
    await expect(page.getByRole('option').first()).toBeVisible()
    await expectWcag22AA(page)
  })
})

test.describe('Main menu', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto(PRODUCT_PATH)
  })

  test('lists the main sections men, women and kids', async ({ page }) => {
    const nav = page.getByRole('navigation', { name: /main/i })
    for (const section of ['Men', 'Women', 'Kids']) {
      await expect(nav.getByRole('button', { name: section })).toBeVisible()
    }
  })

  test('opening a section shows its subsections (APG disclosure)', async ({ page }) => {
    const men = page.getByRole('navigation', { name: /main/i }).getByRole('button', { name: 'Men' })
    await expect(men).toHaveAttribute('aria-expanded', 'false')

    await men.click()

    await expect(men).toHaveAttribute('aria-expanded', 'true')
    const submenu = page.locator(`#${await men.getAttribute('aria-controls')}`)
    await expect(submenu).toBeVisible()
    expect(await submenu.getByRole('link').count()).toBeGreaterThan(0)
  })

  test('closes the section when its button is pressed again', async ({ page }) => {
    const men = page.getByRole('navigation', { name: /main/i }).getByRole('button', { name: 'Men' })
    await men.click()
    await men.click()

    await expect(men).toHaveAttribute('aria-expanded', 'false')
    await expect(page.locator(`#${await men.getAttribute('aria-controls')}`)).toBeHidden()
  })

  test('moves into the subsections with Tab and back out with Shift+Tab', async ({ page }) => {
    const men = page.getByRole('navigation', { name: /main/i }).getByRole('button', { name: 'Men' })
    await men.focus()
    await page.keyboard.press('Enter')
    const firstSubsection = page
      .locator(`#${await men.getAttribute('aria-controls')}`)
      .getByRole('link')
      .first()

    await page.keyboard.press('Tab')
    await expect(firstSubsection).toBeFocused()

    await page.keyboard.press('Shift+Tab')
    await expect(men).toBeFocused()
  })

  test('meets WCAG 2.2 AA with a section open', async ({ page }) => {
    await page.getByRole('navigation', { name: /main/i }).getByRole('button', { name: 'Men' }).click()
    await expectWcag22AA(page)
  })
})

test.describe('Path (breadcrumb)', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto(PRODUCT_PATH)
  })

  test('shows the path to the shoe in order: Shop, Trail, Trail Runner 2', async ({ page }) => {
    const path = page.getByRole('navigation', { name: /breadcrumb/i })
    await expect(path.getByRole('listitem')).toHaveText([/Shop/, /Trail$/, /Trail Runner 2/])
  })

  test('marks the current page with aria-current', async ({ page }) => {
    const path = page.getByRole('navigation', { name: /breadcrumb/i })
    await expect(path.locator('[aria-current="page"]')).toHaveText(/Trail Runner 2/)
    await expect(path.getByRole('link', { name: /Trail Runner 2/ })).toHaveCount(0)
  })

  test('earlier steps are links', async ({ page }) => {
    const path = page.getByRole('navigation', { name: /breadcrumb/i })
    await expect(path.getByRole('link', { name: 'Shop' })).toHaveAttribute('href', /.+/)
    await expect(path.getByRole('link', { name: 'Trail' })).toHaveAttribute('href', /.+/)
  })

  test('goes back to an earlier step when it is chosen', async ({ page }) => {
    await page.getByRole('navigation', { name: /breadcrumb/i }).getByRole('link', { name: 'Trail' }).click()
    await expect(page).not.toHaveURL(new RegExp(`${PRODUCT_PATH}$`))
  })

  test('meets WCAG 2.2 AA', async ({ page }) => {
    await expect(page.getByRole('navigation', { name: /breadcrumb/i })).toBeVisible()
    await expectWcag22AA(page)
  })
})
import { test, expect } from '@playwright/test'
import { PRODUCT_PATH, expectWcag22AA, isRound, chooseAvailableSize } from './helpers.js'

const PRICE = /(€|£|\$|USD|EUR|GBP)\s?\d+([.,]\d{2})?|\d+[.,]\d{2}\s?(€|£)/

test.describe('Photos', () => {
  let gallery
  // Visible photo's src, used to see which photo is on screen.
  const currentSrc = () => gallery.locator('img:visible').first().getAttribute('src')

  test.beforeEach(async ({ page }) => {
    // Fake clock so auto-advance timing is deterministic.
    await page.clock.install()
    await page.goto(PRODUCT_PATH)
    gallery = page.getByRole('region', { name: /photo|image|gallery/i })
  })

  test('shows exactly one photo at a time', async ({ page }) => {
    await expect(gallery).toBeVisible()
    await expect(gallery.locator('img:visible')).toHaveCount(1)
  })

  test('advances to the next photo automatically', async ({ page }) => {
    await expect(gallery).toBeVisible()
    const first = await currentSrc()
    await page.clock.runFor(15_000)
    expect(await currentSrc()).not.toBe(first)
  })

  test('pauses and resumes the automatic advance', async ({ page }) => {
    await expect(gallery).toBeVisible()
    await gallery.getByRole('button', { name: /pause/i }).click()
    await expect(gallery.getByRole('button', { name: /play|resume/i })).toBeVisible()

    const paused = await currentSrc()
    await page.clock.runFor(30_000)
    expect(await currentSrc()).toBe(paused)

    await gallery.getByRole('button', { name: /play|resume/i }).click()
    await page.clock.runFor(15_000)
    expect(await currentSrc()).not.toBe(paused)
  })

  test('moves to the next and previous photo', async ({ page }) => {
    await expect(gallery).toBeVisible()
    await gallery.getByRole('button', { name: /pause/i }).click()
    const start = await currentSrc()

    await gallery.getByRole('button', { name: /next/i }).click()
    const second = await currentSrc()
    expect(second).not.toBe(start)

    await gallery.getByRole('button', { name: /previous|prev/i }).click()
    expect(await currentSrc()).toBe(start)
  })

  test('goes back to the first photo after the last one', async ({ page }) => {
    await expect(gallery).toBeVisible()
    await gallery.getByRole('button', { name: /pause/i }).click()
    const start = await currentSrc()
    const seen = []

    let returned = false
    for (let i = 0; i < 20 && !returned; i++) {
      await gallery.getByRole('button', { name: /next/i }).click()
      const src = await currentSrc()
      if (src === start) returned = true
      else seen.push(src)
    }

    expect(returned, 'Next never wrapped back to the first photo').toBe(true)
    expect(seen.length).toBeGreaterThanOrEqual(1)
    expect(new Set(seen).size).toBe(seen.length)
  })

  test('meets WCAG 2.2 AA', async ({ page }) => {
    await expect(gallery).toBeVisible()
    await expectWcag22AA(page)
  })
})

test.describe('Price', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto(PRODUCT_PATH)
  })

  test('shows the price', async ({ page }) => {
    await expect(page.getByRole('main').getByText(PRICE).first()).toBeVisible()
  })

  test('shows that the price includes taxes when the "i" is pointed at', async ({ page }) => {
    const info = page.getByRole('button', { name: /price info|information about (the )?price/i })
    const tip = page.getByRole('tooltip')
    await expect(tip).toBeHidden()

    await info.hover()
    await expect(tip).toBeVisible()
    await expect(tip).toContainText(/includ\w* .*tax|tax\w* included|incl\. tax/i)
  })

  test('connects the "i" to its explanation (APG tooltip)', async ({ page }) => {
    const info = page.getByRole('button', { name: /price info|information about (the )?price/i })
    await info.hover()
    const tip = page.getByRole('tooltip')
    await expect(tip).toBeVisible()

    const describedBy = (await info.getAttribute('aria-describedby')) ?? ''
    expect(describedBy.split(/\s+/)).toContain(await tip.getAttribute('id'))
  })

  test('shows the explanation when the "i" receives keyboard focus', async ({ page }) => {
    const info = page.getByRole('button', { name: /price info|information about (the )?price/i })
    await info.focus()
    await expect(page.getByRole('tooltip')).toBeVisible()
  })

  test('hides the explanation with Escape without moving focus (WCAG 1.4.13)', async ({ page }) => {
    const info = page.getByRole('button', { name: /price info|information about (the )?price/i })
    await info.focus()
    await expect(page.getByRole('tooltip')).toBeVisible()

    await page.keyboard.press('Escape')
    await expect(page.getByRole('tooltip')).toBeHidden()
    await expect(info).toBeFocused()
  })

  test('keeps the explanation open while it is hovered (WCAG 1.4.13)', async ({ page }) => {
    const info = page.getByRole('button', { name: /price info|information about (the )?price/i })
    await info.hover()
    const tip = page.getByRole('tooltip')
    await expect(tip).toBeVisible()

    await tip.hover()
    await expect(tip).toBeVisible()

    await page.mouse.move(0, 0)
    await expect(tip).toBeHidden()
  })

  test('meets WCAG 2.2 AA with the explanation open', async ({ page }) => {
    const info = page.getByRole('button', { name: /price info|information about (the )?price/i })
    await info.hover()
    await expect(page.getByRole('tooltip')).toBeVisible()
    await expectWcag22AA(page)
  })
})

test.describe('Color', () => {
  let colors
  test.beforeEach(async ({ page }) => {
    await page.goto(PRODUCT_PATH)
    colors = page.getByRole('radiogroup', { name: /color/i })
  })

  test('offers blue, black and grey as round swatches', async ({ page }) => {
    for (const name of ['Blue', 'Black', 'Grey']) {
      await expect(colors.getByRole('radio', { name })).toHaveCount(1)
      const swatch = colors.locator('label', { hasText: name }).locator('[data-testid="swatch"]')
      await expect(swatch).toHaveCount(1)
      expect(await isRound(swatch)).toBe(true)
    }
    await expect(colors.getByRole('radio')).toHaveCount(3)
  })

  test('has exactly one chosen color at a time', async ({ page }) => {
    await expect(colors.getByRole('radio', { checked: true })).toHaveCount(1)
    await colors.getByRole('radio', { name: 'Black' }).click()
    await expect(colors.getByRole('radio', { name: 'Black' })).toBeChecked()
    await expect(colors.getByRole('radio', { checked: true })).toHaveCount(1)
  })

  test('shows the chosen color on the photos', async ({ page }) => {
    await colors.getByRole('radio', { name: 'Black' }).click()
    const gallery = page.getByRole('region', { name: /photo|image|gallery/i })
    await expect(gallery.locator('img:visible').first()).toHaveAttribute('alt', /black/i)
  })

  test('moves between colors with arrow keys (APG radio group)', async ({ page }) => {
    await colors.getByRole('radio', { name: 'Blue' }).focus()
    await page.keyboard.press('ArrowRight')
    await expect(colors.getByRole('radio', { name: 'Black' })).toBeChecked()
    await expect(colors.getByRole('radio', { name: 'Black' })).toBeFocused()
  })

  test('meets WCAG 2.2 AA', async ({ page }) => {
    await expect(colors).toBeVisible()
    await expectWcag22AA(page)
  })
})

test.describe('Size', () => {
  let size
  test.beforeEach(async ({ page }) => {
    await page.goto(PRODUCT_PATH)
    size = page.getByRole('combobox', { name: /size/i })
  })

  test('shows no size list until the shopper opens it (APG select-only combobox)', async ({ page }) => {
    await expect(size).toHaveAttribute('aria-expanded', 'false')
    await expect(size).toHaveAttribute('aria-haspopup', 'listbox')
    await expect(page.getByRole('listbox')).toBeHidden()
  })

  test('opens the size list and it lists sizes', async ({ page }) => {
    await size.click()
    await expect(size).toHaveAttribute('aria-expanded', 'true')
    const listbox = page.locator(`#${await size.getAttribute('aria-controls')}`)
    await expect(listbox).toBeVisible()
    expect(await listbox.getByRole('option').count()).toBeGreaterThan(1)
  })

  test('starts with no size chosen', async ({ page }) => {
    await size.click()
    await expect(page.getByRole('listbox').locator('[aria-selected="true"]')).toHaveCount(0)
  })

  test('marks at least one size as sold out and does not let it be picked', async ({ page }) => {
    await size.click()
    const soldOut = page.getByRole('listbox').locator('[role="option"][aria-disabled="true"]').first()
    await expect(soldOut).toBeVisible()

    const before = await size.textContent()
    await soldOut.click()
    await expect(soldOut).toHaveAttribute('aria-selected', 'false')
    await expect(size).toHaveText(before)
  })

  test('shows only the chosen size after a choice is made and closes the list', async ({ page }) => {
    const chosen = await chooseAvailableSize(page)
    const chosenText = (await chosen.textContent())?.trim()

    await expect(size).toHaveAttribute('aria-expanded', 'false')
    await expect(page.getByRole('listbox')).toBeHidden()
    await expect(size).toContainText(chosenText)
  })

  test('chooses a size with the keyboard and closes the list with Escape', async ({ page }) => {
    await size.focus()
    await page.keyboard.press('ArrowDown')
    await expect(size).toHaveAttribute('aria-expanded', 'true')

    const before = await size.textContent()
    await page.keyboard.press('Escape')
    await expect(size).toHaveAttribute('aria-expanded', 'false')
    await expect(size).toBeFocused()
    await expect(size).toHaveText(before)
  })

  test('meets WCAG 2.2 AA with the list open', async ({ page }) => {
    await size.click()
    await expect(page.getByRole('listbox')).toBeVisible()
    await expectWcag22AA(page)
  })
})

test.describe('Store availability', () => {
  let grid
  test.beforeEach(async ({ page }) => {
    await page.goto(PRODUCT_PATH)
    grid = page.getByRole('grid', { name: /store|availability|pick ?up/i })
  })

  test('shows nearby stores as rows and sizes as columns', async ({ page }) => {
    await expect(grid).toBeVisible()
    expect(await grid.getByRole('rowheader').count()).toBeGreaterThanOrEqual(2)
    expect(await grid.getByRole('columnheader').count()).toBeGreaterThanOrEqual(2)
  })

  test('marks unavailable store and size combinations', async ({ page }) => {
    await expect(grid).toBeVisible()
    await expect(grid.locator('[aria-disabled="true"]').first()).toBeVisible()
  })

  test('has one tab stop, and arrow keys move between cells (APG grid)', async ({ page }) => {
    await expect(grid).toBeVisible()
    await expect(grid.locator('[tabindex="0"]')).toHaveCount(1)

    const cells = grid.getByRole('gridcell')
    const rows = await grid.getByRole('row').count()
    const columns = (await cells.count()) / rows
    expect(Number.isInteger(columns) && columns > 1).toBe(true)

    await grid.locator('[tabindex="0"]').focus()
    await page.keyboard.press('ArrowRight')
    await expect(cells.nth(1)).toBeFocused()

    await page.keyboard.press('ArrowDown')
    await expect(cells.nth(1 + columns)).toBeFocused()
  })

  test('picks an available store and size combination for pickup', async ({ page }) => {
    await expect(grid).toBeVisible()
    const available = grid.locator('[role="gridcell"]:not([aria-disabled="true"])').first()
    await available.focus()
    await page.keyboard.press('Enter')

    await expect(available).toHaveAttribute('aria-selected', 'true')
    await expect(page.getByRole('main')).toContainText(/pick ?up/i)
  })

  test('does not pick an unavailable combination', async ({ page }) => {
    await expect(grid).toBeVisible()
    const unavailable = grid.locator('[role="gridcell"][aria-disabled="true"]').first()
    await unavailable.click({ force: true })
    await expect(unavailable).not.toHaveAttribute('aria-selected', 'true')
  })

  test('meets WCAG 2.2 AA', async ({ page }) => {
    await expect(grid).toBeVisible()
    await expectWcag22AA(page)
  })
})

test.describe('Size guide', () => {
  let trigger
  let dialog
  test.beforeEach(async ({ page }) => {
    await page.goto(PRODUCT_PATH)
    trigger = page.getByRole('button', { name: /size guide/i })
    dialog = page.getByRole('dialog', { name: /size guide/i })
  })

  test('opens a size chart over the page from next to the size', async ({ page }) => {
    await trigger.click()
    await expect(dialog).toBeVisible()
    await expect(dialog).toHaveAttribute('aria-modal', 'true')
  })

  test('moves focus into the dialog when it opens', async ({ page }) => {
    await trigger.click()
    await expect(dialog).toBeVisible()
    const focusInside = await page.evaluate(() => !!document.activeElement?.closest('[role="dialog"]'))
    expect(focusInside).toBe(true)
  })

  test('keeps keyboard focus inside the dialog while it is open', async ({ page }) => {
    await trigger.click()
    await expect(dialog).toBeVisible()
    for (let i = 0; i < 30; i++) {
      await page.keyboard.press('Tab')
      const inside = await page.evaluate(() => !!document.activeElement?.closest('[role="dialog"]'))
      expect(inside, `focus escaped the dialog after ${i + 1} Tab presses`).toBe(true)
    }
  })

  test('makes the page behind it unavailable until it is closed', async ({ page }) => {
    await trigger.click()
    await expect(dialog).toBeVisible()
    const addToCart = page.getByRole('button', { name: /add to cart/i })
    const hidden = await addToCart.evaluate((el) => !!el.closest('[inert], [aria-hidden="true"]'))
    expect(hidden).toBe(true)
  })

  test('closes with Escape and returns focus to the button that opened it', async ({ page }) => {
    await trigger.click()
    await expect(dialog).toBeVisible()
    await page.keyboard.press('Escape')
    await expect(dialog).toBeHidden()
    await expect(trigger).toBeFocused()
