test.describe('Delivery date', () => {
  let trigger
  let dialog
  test.beforeEach(async ({ page }) => {
    await page.goto(PRODUCT_PATH)
    trigger = page.getByRole('button', { name: /delivery date/i })
    dialog = page.getByRole('dialog', { name: /delivery date/i })
  })

  test('opens a calendar from a button (APG date picker dialog)', async ({ page }) => {
    await expect(trigger).toHaveAttribute('aria-expanded', 'false')
    await trigger.click()
    await expect(dialog).toBeVisible()
    await expect(trigger).toHaveAttribute('aria-expanded', 'true')
    await expect(dialog.getByRole('grid')).toBeVisible()
  })

  test('moves focus to a day when the calendar opens', async ({ page }) => {
    await trigger.click()
    const focusedDay = dialog.locator('[role="gridcell"][tabindex="0"]')
    await expect(focusedDay).toHaveCount(1)
    await expect(focusedDay).toBeFocused()
  })

  test('moves between days with arrow keys', async ({ page }) => {
    await trigger.click()
    const focusedDay = dialog.locator('[role="gridcell"][tabindex="0"]')
    const before = await focusedDay.getAttribute('aria-label')
    await page.keyboard.press('ArrowRight')
    await expect(dialog.locator('[role="gridcell"][tabindex="0"]')).not.toHaveAttribute('aria-label', before)
    await expect(dialog.locator('[role="gridcell"][tabindex="0"]')).toBeFocused()
  })

  test('moves to the next and previous month with the buttons', async ({ page }) => {
    await trigger.click()
    const grid = dialog.getByRole('grid')
    const now = new Date()
    const monthName = (offset) =>
      new Date(now.getFullYear(), now.getMonth() + offset, 1).toLocaleString('en-US', { month: 'long' })

    await dialog.getByRole('button', { name: /next month/i }).click()
    await expect(grid).toHaveAccessibleName(new RegExp(monthName(1)))

    await dialog.getByRole('button', { name: /previous month/i }).click()
    await expect(grid).toHaveAccessibleName(new RegExp(monthName(0)))
  })

  test('moves to another month with the keyboard (PageDown)', async ({ page }) => {
    await trigger.click()
    const grid = dialog.getByRole('grid')
    const now = new Date()
    const nextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1).toLocaleString('en-US', { month: 'long' })

    await page.keyboard.press('PageDown')
    await expect(grid).toHaveAccessibleName(new RegExp(nextMonth))
  })

  test('does not choose a day that is not available', async ({ page }) => {
    await trigger.click()
    const unavailable = dialog.locator('[role="gridcell"][aria-disabled="true"]').first()
    await expect(unavailable).toBeVisible()
    await unavailable.click({ force: true })
    await expect(dialog).toBeVisible()
    await expect(unavailable).not.toHaveAttribute('aria-selected', 'true')
  })

  test('shows the chosen date on the page', async ({ page }) => {
    await trigger.click()
    const day = dialog.locator('[role="gridcell"]:not([aria-disabled="true"])').first()
    const label = (await day.getAttribute('aria-label')) ?? ''
    const parts = label.match(/([A-Za-z]+)\s+(\d{1,2})\b/)
    expect(parts, `day cell needs an aria-label with month and day, got "${label}"`).not.toBeNull()
    const [, month, dayNumber] = parts

    await day.click()
    await expect(dialog).toBeHidden()
    await expect(trigger).toBeFocused()
    await expect(page.getByRole('main')).toContainText(month)
    await expect(page.getByRole('main')).toContainText(new RegExp(`\\b${dayNumber}\\b`))
  })

  test('closes with Escape and returns focus to the trigger', async ({ page }) => {
    await trigger.click()
    await page.keyboard.press('Escape')
    await expect(dialog).toBeHidden()
    await expect(trigger).toBeFocused()
  })

  test('meets WCAG 2.2 AA with the calendar open', async ({ page }) => {
    await trigger.click()
    await expect(dialog).toBeVisible()
    await expectWcag22AA(page)
  })
})

