    await expect(tablist.getByRole('tab', { name: 'Reviews' })).toHaveAttribute('aria-selected', 'true')

    await page.keyboard.press('End')
    await expect(tablist.getByRole('tab', { name: 'Shipping' })).toBeFocused()

    await page.keyboard.press('Home')
    await expect(tablist.getByRole('tab', { name: 'Details' })).toBeFocused()
