import { useEffect, useState } from 'react'

const VIEWS = ['Front', 'Side', 'Back', 'Sole']
const INTERVAL_MS = 4000

// Placeholder illustrations (no product photography was supplied).
function shoeSvg(colorHex, view) {
  const rot = { Front: 0, Side: 0, Back: 0, Sole: 0 }[view]
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 450">
    <rect width="600" height="450" fill="#e9ecef"/>
    <text x="24" y="40" font-family="sans-serif" font-size="22" fill="#495057">${view}</text>
    <g transform="rotate(${rot} 300 225)">
      <path d="M130 300 Q150 200 260 190 L330 150 Q350 140 360 175 L400 250 Q470 270 470 310 L130 330 Z" fill="${colorHex}"/>
      <path d="M130 330 L470 330 L470 350 L130 350 Z" fill="#343a40"/>
    </g>
  </svg>`
}

export default function Gallery({ colors, colorId }) {
  const color = colors.find((c) => c.id === colorId) ?? colors[0]
  const slides = VIEWS.map((view) => ({
    alt: `Trail Runner 2 in ${color.name.toLowerCase()}, ${view.toLowerCase()} view`,
    src: `data:image/svg+xml;charset=utf-8,${encodeURIComponent(shoeSvg(color.hex, view))}`,
  }))
  const [index, setIndex] = useState(0)
  const [playing, setPlaying] = useState(true)

  useEffect(() => {
    if (!playing) return undefined
    const id = setInterval(() => setIndex((i) => (i + 1) % slides.length), INTERVAL_MS)
    return () => clearInterval(id)
  }, [playing, slides.length])

  const current = slides[index % slides.length]
  return (
    <section className="gallery" role="region" aria-label="Product photos">
      <div className="stage">
        {slides.map((s, i) => (
          <img key={s.src} src={s.src} alt={s.alt} hidden={i !== index % slides.length} />
        ))}
      </div>
      <div className="controls">
        <button type="button" aria-label="Previous photo" onClick={() => setIndex((i) => (i - 1 + slides.length) % slides.length)}>
          ←
        </button>
        <button type="button" aria-label={playing ? 'Pause slideshow' : 'Play slideshow'} onClick={() => setPlaying((p) => !p)}>
          {playing ? 'Pause' : 'Play'}
        </button>
        <button type="button" aria-label="Next photo" onClick={() => setIndex((i) => (i + 1) % slides.length)}>
          →
        </button>
        <span aria-hidden="true">{`${(index % slides.length) + 1} / ${slides.length}`}</span>
      </div>
      <span className="visually-hidden">{current.alt}</span>
    </section>
  )
}
