        type="number"
        min="1"
        value={value}
        onChange={(e) => onChange(e.target.value === '' ? '' : clamp(Number(e.target.value)))}
        onBlur={() => onChange(clamp(Number(value)))}
      />
      <button type="button" aria-label="Increase quantity" onClick={() => onChange(clamp(value + 1))}>
        +
      </button>
    </div>
  )
}

export function Wishlist({ pressed, onToggle }) {
  return (
    <button type="button" className="wishlist" aria-pressed={pressed} onClick={onToggle}>
      <span aria-hidden="true">{pressed ? '♥' : '♡'}</span> Wishlist
    </button>
