const DAY_MS = 24 * 60 * 60 * 1000
const startOfDay = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate())
const fmt = (d) =>
  d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })

// Earliest delivery is two days out; Sundays are never available.
function isAvailable(d, today) {
  return d.getTime() - today.getTime() >= 2 * DAY_MS && d.getDay() !== 0
}

export function DeliveryDate({ chosen, onChoose }) {
  const dialogId = useId()
  const [open, setOpen] = useState(false)
  const today = startOfDay(new Date())
  const [month, setMonth] = useState(() => new Date(today.getFullYear(), today.getMonth(), 1))
  const [focusDay, setFocusDay] = useState(null)
  const triggerRef = useRef(null)
  const gridRef = useRef(null)
  const didOpen = useRef(false)

  useEffect(() => {
    if (!open || !didOpen.current) return
    const cell = gridRef.current?.querySelector('[tabindex="0"]')
    cell?.focus()
  }, [open, focusDay, month])

  function openCal() {
    const start = chosen ?? firstAvailable(today)
    setFocusDay(start)
    setMonth(new Date(start.getFullYear(), start.getMonth(), 1))
    didOpen.current = true
    setOpen(true)
  }

  function close() {
    didOpen.current = false
    setOpen(false)
    triggerRef.current?.focus()
  }

  function firstAvailable(base) {
    for (let i = 0; i < 60; i++) {
      const d = new Date(base.getFullYear(), base.getMonth(), base.getDate() + i)
      if (isAvailable(d, today)) return d
    }
    return base
  }

  function moveFocus(d) {
    setFocusDay(d)
    if (d.getMonth() !== month.getMonth() || d.getFullYear() !== month.getFullYear()) {
      setMonth(new Date(d.getFullYear(), d.getMonth(), 1))
    }
  }

  function onGridKey(e) {
    const base = focusDay
    const step = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: 7, ArrowUp: -7 }[e.key]
    if (step) {
      e.preventDefault()
      moveFocus(new Date(base.getFullYear(), base.getMonth(), base.getDate() + step))
    } else if (e.key === 'PageDown' || e.key === 'PageUp') {
      e.preventDefault()
      const dir = e.key === 'PageDown' ? 1 : -1
      moveFocus(new Date(base.getFullYear(), base.getMonth() + dir, base.getDate()))
    } else if (e.key === 'Escape') {
      e.preventDefault()
      close()
    }
  }

  // Build the weeks of the visible month (Sunday-first).
  const first = new Date(month.getFullYear(), month.getMonth(), 1)
  const days = []
  const lead = first.getDay()
  for (let i = -lead; i < 42 - lead; i++) days.push(new Date(first.getFullYear(), first.getMonth(), 1 + i))
  const monthName = first.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })

  return (
    <div className="delivery">
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={dialogId}
        onClick={() => (open ? close() : openCal())}
      >
        Delivery date
      </button>
      {chosen && <p className="chosen-date">Arrives {fmt(chosen)}</p>}
      <div id={dialogId} role="dialog" aria-labelledby={`${dialogId}-title`} hidden={!open} className="calendar">
        <h3 id={`${dialogId}-title`}>Delivery date</h3>
        <div className="cal-nav">
          <button type="button" aria-label="Previous month" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1))}>
            ‹
          </button>
          <span>{monthName}</span>
          <button type="button" aria-label="Next month" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1))}>
            ›
          </button>
        </div>
        <table role="grid" aria-label={monthName} ref={gridRef} onKeyDown={onGridKey}>
          <thead>
            <tr role="row">
              {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map((d) => (
                <th key={d} role="columnheader" scope="col" abbr={d}>
                  {d}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {Array.from({ length: 6 }, (_, w) => (
              <tr role="row" key={w}>
                {days.slice(w * 7, w * 7 + 7).map((d) => {
                  const avail = isAvailable(d, today)
                  const label = d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })
                  const selected = chosen && startOfDay(d).getTime() === startOfDay(chosen).getTime()
                  const focused = focusDay && startOfDay(d).getTime() === startOfDay(focusDay).getTime()
                  return (
                    <td
                      key={d.getTime()}
                      role="gridcell"
                      aria-label={label}
                      aria-disabled={!avail}
                      aria-selected={selected ? 'true' : undefined}
                      tabIndex={focused ? 0 : -1}
                      className={[
                        d.getMonth() !== first.getMonth() ? 'outside' : '',
                        avail ? '' : 'unavailable',
                        selected ? 'selected' : '',
                      ].join(' ').trim()}
                      onClick={() => {
                        if (!avail) return
                        onChoose(startOfDay(d))
                        close()
                      }}
                      onFocus={() => setFocusDay(startOfDay(d))}
                    >
                      {d.getDate()}
                    </td>
                  )
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}
