import { createPortal } from 'react-dom'
import { useEffect, useId, useRef, useState } from 'react'
import { product } from '../data/product.js'

const SIZES = product.sizes.map((s) => s.label)

export function StoreGrid({ pickup, onPick }) {
  const [focus, setFocus] = useState({ r: 0, c: 0 })
  const refs = useRef({})
  const rows = product.stores
  const cellRefs = refs.current

  function move(r, c) {
    const nr = Math.min(rows.length - 1, Math.max(0, r))
    const nc = Math.min(SIZES.length - 1, Math.max(0, c))
    setFocus({ r: nr, c: nc })
    cellRefs[`${nr}-${nc}`]?.focus()
  }

  function onKeyDown(e, r, c) {
    const keys = { ArrowRight: [0, 1], ArrowLeft: [0, -1], ArrowDown: [1, 0], ArrowUp: [-1, 0] }
    if (keys[e.key]) {
      e.preventDefault()
      const [dr, dc] = keys[e.key]
      move(r + dr, c + dc)
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      if (rows[r].stock[SIZES[c]]) onPick({ store: rows[r].name, size: SIZES[c] })
    }
  }

  const selectedId = pickup ? `${rows.findIndex((s) => s.name === pickup.store)}-${SIZES.indexOf(pickup.size)}` : null

  return (
    <div className="store-grid">
      <p id="store-grid-label">Pick up in store</p>
      <table role="grid" aria-labelledby="store-grid-label">
        <thead>
          <tr role="row">
            <th role="columnheader" scope="col">Store</th>
            {SIZES.map((s) => (
              <th key={s} role="columnheader" scope="col">US {s}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((store, r) => (
            <tr role="row" key={store.name}>
              <th role="rowheader" scope="row">{store.name}</th>
              {SIZES.map((size, c) => {
                const ok = !!store.stock[size]
                const id = `${r}-${c}`
                const isFocus = focus.r === r && focus.c === c
                return (
                  <td
                    key={size}
                    role="gridcell"
                    ref={(el) => { if (el) cellRefs[id] = el; else delete cellRefs[id] }}
                    tabIndex={isFocus ? 0 : -1}
                    aria-disabled={!ok}
                    aria-selected={selectedId === id ? 'true' : undefined}
                    aria-label={`${store.name}, US ${size}, ${ok ? 'in stock' : 'sold out'}`}
                    onFocus={() => setFocus({ r, c })}
                    onKeyDown={(e) => onKeyDown(e, r, c)}
                    onClick={() => {
                      if (ok) {
                        setFocus({ r, c })
                        onPick({ store: store.name, size })
                      }
                    }}
                  >
                    {ok ? 'In stock' : 'Sold out'}
                  </td>
                )
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

const FOCUSABLE = 'button, [href], input, [tabindex]:not([tabindex="-1"]), select, textarea'

export function SizeGuide({ onClose, triggerRef }) {
  const titleId = useId()
  const dialogRef = useRef(null)
  const [length, setLength] = useState('')
  const [unit, setUnit] = useState('US')
  const [submitted, setSubmitted] = useState(null)

  useEffect(() => {
    dialogRef.current?.querySelector('input')?.focus()
    const root = document.getElementById('app-root')
    if (root) root.inert = true
    return () => {
      if (root) root.inert = false
    }
  }, [])

  function close() {
    onClose()
    triggerRef.current?.focus()
  }

  function onKeyDown(e) {
    if (e.key === 'Escape') {
      e.preventDefault()
      close()
      return
    }
    if (e.key !== 'Tab') return
    const items = [...dialogRef.current.querySelectorAll(FOCUSABLE)].filter((el) => !el.disabled && el.offsetParent !== null)
    if (!items.length) return
    const first = items[0]
    const last = items[items.length - 1]
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault()
      last.focus()
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault()
      first.focus()
    }
  }

  let result = null
  if (submitted) {
    const eu = Math.round((submitted + 1.5) * 1.5)
    const us = eu - 33
    result = unit === 'US' ? `US ${us}` : `EU ${eu}`
  }

  return createPortal(
    <div className="overlay">
      <div ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby={titleId} className="size-guide" onKeyDown={onKeyDown}>
        <h2 id={titleId}>Size guide</h2>
        <form
          onSubmit={(e) => {
            e.preventDefault()
            const n = Number(length)
            setSubmitted(n > 0 ? n : null)
          }}
        >
          <label>
            Foot length (cm){' '}
            <input type="number" step="0.1" min="10" max="35" value={length} onChange={(e) => setLength(e.target.value)} />
          </label>
          <fieldset>
            <legend>Size system</legend>
            <label><input type="radio" name="unit" value="US" checked={unit === 'US'} onChange={() => setUnit('US')} /> US</label>
            <label><input type="radio" name="unit" value="EU" checked={unit === 'EU'} onChange={() => setUnit('EU')} /> EU</label>
          </fieldset>
          <button type="submit">Find my size</button>
        </form>
        <p role="status">{result ? `Your size: ${result}` : ''}</p>
        <table>
          <caption>Size chart</caption>
          <thead>
            <tr><th scope="col">US</th><th scope="col">EU</th></tr>
          </thead>
          <tbody>
            {[8, 9, 10, 11].map((us) => (
              <tr key={us}><td>{us}</td><td>{us + 33}</td></tr>
            ))}
          </tbody>
        </table>
        <button type="button" onClick={close}>Close size guide</button>
      </div>
    </div>,
    document.body,
  )
}
