const TABS = [
  { key: 'details', label: 'Details', body: 'Trail Runner 2 has a 6 mm lug outsole, a rock plate under the midsole and a breathable mesh upper. Weight: 280 g (US 9).' },
  { key: 'reviews', label: 'Reviews', body: 'Rated 4.6 out of 5 by 128 runners. "Grippy on wet roots and comfortable on 30 km runs."' },
  { key: 'shipping', label: 'Shipping', body: 'Free standard delivery on orders over $75. Returns accepted within 30 days of delivery.' },
