export function MoreInfo() {
  const [selected, setSelected] = useState(0)
  const tabRefs = useRef([])
  const base = useId()

  function activate(i) {
    setSelected(i)
    tabRefs.current[i]?.focus()
  }

  function onKeyDown(e, i) {
    const last = TABS.length - 1
    if (e.key === 'ArrowRight') { e.preventDefault(); activate(i === last ? 0 : i + 1) }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); activate(i === 0 ? last : i - 1) }
    else if (e.key === 'Home') { e.preventDefault(); activate(0) }
    else if (e.key === 'End') { e.preventDefault(); activate(last) }
  }

  return (
    <section className="more-info" aria-labelledby={`${base}-heading`}>
      <h2 id={`${base}-heading`} className="visually-hidden">More information</h2>
      <div role="tablist" aria-label="More information" className="tabs">
