.suggestions li[aria-selected="true"] { background: #e7eef8; }
.cart { text-decoration: none; font-weight: 600; }
.main-menu { display: flex; gap: 20px; list-style: none; margin: 10px 0 0; padding: 0; flex-wrap: wrap; }
.main-menu > li { position: relative; }
.main-menu button { background: none; border: 0; padding: 4px 0; cursor: pointer; font-weight: 600; }
.submenu { position: absolute; top: 100%; left: 0; list-style: none; margin: 0; padding: 8px 12px; background: #fff; border: 1px solid #d0d4da; min-width: 160px; z-index: 4; }

.breadcrumb ol { display: flex; flex-wrap: wrap; gap: 8px; list-style: none; margin: 0; padding: 12px 16px; font-size: 0.9rem; }
.breadcrumb li + li::before { content: "/"; margin-right: 8px; color: #6b6f76; }

.product { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: 32px; padding: 16px; max-width: 1200px; margin: 0 auto; }
@media (max-width: 760px) { .product { grid-template-columns: 1fr; } }
.gallery { position: relative; }
.gallery .stage { background: #f1f3f5; }
.gallery .controls { display: flex; gap: 8px; align-items: center; margin-top: 8px; }
.gallery .controls button { min-width: 44px; min-height: 44px; border: 1px solid #8a8d91; background: #fff; border-radius: 4px; cursor: pointer; }
.buy > * + * { margin-top: 16px; }
.buy h1 { margin: 0; font-size: 1.75rem; }
.price-row { position: relative; display: inline-block; }
.price { margin: 0; font-size: 1.4rem; font-weight: 600; }
.info { width: 24px; height: 24px; min-width: 24px; border-radius: 50%; border: 1px solid #1d1d1f; background: #fff; margin-left: 6px; cursor: pointer; font-size: 0.8rem; }
.tooltip { position: absolute; left: 0; top: 100%; background: #1d1d1f; color: #fff; padding: 8px 10px; border-radius: 4px; width: max-content; max-width: 260px; font-size: 0.85rem; z-index: 3; }
.colors { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.swatch-option { position: relative; display: inline-flex; align-items: center; gap: 6px; cursor: pointer; }
.swatch-option input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
.swatch { width: 32px; height: 32px; border-radius: 50%; border: 2px solid #d0d4da; display: inline-block; }
.swatch-option input:checked + .swatch { border-color: #1d1d1f; box-shadow: inset 0 0 0 3px #fff; }
.swatch-option input:focus-visible + .swatch { outline: 3px solid #0b5cad; outline-offset: 2px; }
.size-row { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.size-select { position: relative; }
.size-trigger { min-width: 160px; padding: 10px 12px; border: 1px solid #8a8d91; border-radius: 4px; cursor: pointer; background: #fff; }
.size-trigger[aria-invalid="true"] { border: 2px solid #b00020; }
.size-list { position: absolute; top: 100%; left: 0; right: 0; list-style: none; margin: 4px 0 0; padding: 4px; background: #fff; border: 1px solid #8a8d91; z-index: 6; }
.size-list li { padding: 8px 10px; cursor: pointer; }
.size-list li.active { background: #e7eef8; }
.size-list li[aria-disabled="true"] { color: #6b6f76; text-decoration: line-through; cursor: not-allowed; }
.size-list li[aria-selected="true"] { font-weight: 700; }
.link { background: none; border: 0; text-decoration: underline; cursor: pointer; padding: 0; }
.error { color: #b00020; font-weight: 600; margin: 0; }
.overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.5); display: grid; place-items: center; padding: 16px; z-index: 20; }
.size-guide { background: #fff; padding: 24px; border-radius: 8px; max-width: 420px; width: 100%; max-height: 90vh; overflow: auto; }
.size-guide table { border-collapse: collapse; margin-top: 12px; }
.size-guide td, .size-guide th { border: 1px solid #d0d4da; padding: 4px 10px; }
.size-guide label { display: block; margin: 8px 0; }
.size-guide fieldset { border: 0; padding: 0; }
.store-grid table { border-collapse: collapse; width: 100%; font-size: 0.85rem; }
.store-grid th, .store-grid td { border: 1px solid #d0d4da; padding: 6px; text-align: center; }
.store-grid th[scope="row"] { text-align: left; }
.store-grid td { cursor: pointer; }
.store-grid td[aria-disabled="true"] { color: #6b6f76; background: #f1f3f5; cursor: not-allowed; }
.store-grid td[aria-selected="true"] { background: #1d1d1f; color: #fff; }
.quantity { display: flex; gap: 8px; align-items: center; }
.quantity input { width: 64px; padding: 8px; text-align: center; border: 1px solid #8a8d91; border-radius: 4px; }
.quantity button { width: 44px; height: 44px; border: 1px solid #8a8d91; background: #fff; border-radius: 4px; cursor: pointer; }
.delivery { position: relative; }
.delivery > button { padding: 10px 14px; border: 1px solid #8a8d91; background: #fff; border-radius: 4px; cursor: pointer; }
.chosen-date { font-weight: 600; margin: 8px 0 0; }
.calendar { position: absolute; top: 100%; left: 0; background: #fff; border: 1px solid #8a8d91; padding: 12px; border-radius: 6px; z-index: 7; }
.calendar table { border-collapse: collapse; }
.calendar th, .calendar td { width: 36px; height: 36px; text-align: center; padding: 0; }
.calendar td[role="gridcell"] { cursor: pointer; }
.calendar td.unavailable { color: #8a8d91; text-decoration: line-through; cursor: not-allowed; }
.calendar td.outside { color: #8a8d91; }
.calendar td.selected { background: #1d1d1f; color: #fff; }
.cal-nav { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.cal-nav button { width: 36px; height: 36px; cursor: pointer; }
.add-to-cart { width: 100%; padding: 14px; background: #0b5cad; color: #fff; border: 0; border-radius: 4px; font-weight: 600; font-size: 1rem; cursor: pointer; }
.cart-status { font-weight: 600; min-height: 1.4em; }
.wishlist { background: none; border: 1px solid #8a8d91; border-radius: 4px; padding: 10px 14px; cursor: pointer; }
.heart { display: inline-block; width: 12px; height: 12px; border: 2px solid currentColor; border-radius: 50% 50% 0 0; vertical-align: middle; }
.heart.on { background: #b00020; border-color: #b00020; }
.wishlist[aria-pressed="true"] { border-color: #b00020; }
.field-label { font-weight: 600; }

.questions, .more-info { max-width: 1200px; margin: 24px auto; padding: 0 16px; }
.questions h2 { font-size: 1.25rem; }
.qa { border-top: 1px solid #d0d4da; }
.qa h3 { margin: 0; }
.qa button { width: 100%; text-align: left; padding: 14px 0; background: none; border: 0; font-weight: 600; cursor: pointer; }
.qa p { margin: 0 0 14px; }
.tabs { display: flex; gap: 8px; border-bottom: 1px solid #d0d4da; flex-wrap: wrap; }
.tabs button { padding: 10px 14px; background: none; border: 0; border-bottom: 3px solid transparent; cursor: pointer; }
.tabs button[aria-selected="true"] { border-bottom-color: #1d1d1f; font-weight: 600; }
.tabpanel { padding: 16px 0; }

footer { background: #f1f3f5; padding: 32px 16px; display: flex; gap: 32px; flex-wrap: wrap; }
.footer-group { min-width: 160px; flex: 1 1 160px; }
.footer-group h2 { font-size: 1rem; margin: 0 0 8px; }
.footer-group div { display: flex; flex-direction: column; gap: 6px; }
EOF
